import{_ as n,W as p,s as r,u,I as s,ah as a,w as e,Z as l,A as i}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const w=JSON.parse('{"title":"使用 FVWM 自定义 Linux 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"使用 FVWM 自定义 Linux 桌面 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"使用 FVWM 自定义 Linux 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 FVWM 自定义 Linux 桌面 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191210 Customize your Linux desktop with FVWM","title":"使用 FVWM 自定义 Linux 桌面","tag":"201912"},"relativePath":"201912/20191210 Customize your Linux desktop with FVWM.md","filePath":"[post].md"}'),d={name:"201912/20191210 Customize your Linux desktop with FVWM.md"};function m(f,t,M,g,x,V){const o=p("Link");return u(),r("div",null,[t[25]||(t[25]=s("h1",{id:"使用-fvwm-自定义-linux-桌面",tabindex:"-1"},[e("使用 FVWM 自定义 Linux 桌面 "),s("a",{class:"header-anchor",href:"#使用-fvwm-自定义-linux-桌面","aria-label":"Permalink to 使用 FVWM 自定义 Linux 桌面"},"​")],-1)),t[26]||(t[26]=s("blockquote",null,[s("p",null,"本文是 24 天 Linux 桌面特别系列的一部分。如果你正在寻找轻巧、快速且简单的 Linux 窗口管理器，那么 FVWM 可以胜任。但是，如果你正在寻找可以深入、探索和魔改的窗口管理器，那么 FVWM 是必须的。")],-1)),t[27]||(t[27]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/25/062800dwh3yhfcpx3ggjxp.jpg",alt:""})],-1)),s("p",null,[l(o,{href:"http://www.fvwm.org/"},{default:i(()=>t[0]||(t[0]=[e("FVWM")])),_:1}),t[2]||(t[2]=e(" 窗口管理器最早脱胎于对 1993 年的 ")),l(o,{href:"https://en.wikipedia.org/wiki/Twm"},{default:i(()=>t[1]||(t[1]=[e("TWM")])),_:1}),t[3]||(t[3]=e(" 的修改。经过几年的迭代，诞生了一个可高度自定义的环境，它可以配置任何行为、动作或事件。它支持自定义键绑定、鼠标手势、主题、脚本等。"))]),s("p",null,[t[5]||(t[5]=e("尽管 FVWM 在安装后即可投入使用，但默认分发版本仅提供了极其少的配置。这是开始自定义桌面环境的良好基础，但是，如果你只想将其用作桌面，那么可能要安装由其它用户发布的完整配置版本。FVWM 有几种不同的分发版，包括模仿 Windows 95 的 FVWM95（至少在外观和布局上）。我尝试了 ")),l(o,{href:"https://www.box-look.org/p/1018270/"},{default:i(()=>t[4]||(t[4]=[e("FVWM-Crystal")])),_:1}),t[6]||(t[6]=e("，这是一个具有一些现代 Linux 桌面约定的现代主题。"))]),s("p",null,[t[8]||(t[8]=e("可以从 Linux 发行版的软件仓库中安装要尝试的 FVWM 分发版。如果找不到特定的 FVWM 分发版，那么可以安装基础的 FVWM2 包，然后进入 ")),l(o,{href:"http://box-look.org"},{default:i(()=>t[7]||(t[7]=[e("Box-Look.org")])),_:1}),t[9]||(t[9]=e(" 手动下载主题包。这样就需要更多的工作，但比从头开始构建要少。"))]),t[28]||(t[28]=a('<p>安装后，请注销当前的桌面会话，以便你可以登录 FVWM。默认情况下，会话管理器（KDM、GDM、LightDM 或 XDM，取决于你的设置）将继续登录到以前的桌面，因此你必须在登录之前覆盖该桌面。</p><p>对于 GDM：</p><p><img src="https://opensource.com/sites/default/files/advent-gdm_0.jpg" alt="Select your desktop session in GDM" title="Select your desktop session in GDM"></p><p>对于 KDM：</p><p><img src="https://opensource.com/sites/default/files/advent-kdm.jpg" alt="Select your desktop session with KDM" title="Select your desktop session with KDM"></p><h3 id="fvwm-桌面" tabindex="-1">FVWM 桌面 <a class="header-anchor" href="#fvwm-桌面" aria-label="Permalink to FVWM 桌面">​</a></h3><p>无论你使用什么主题和配置，当你在桌面上单击鼠标左键时，FVWM 至少会显示一个菜单。菜单的内容取决于你所安装的内容。FVWM-Crystal 分发版中的菜单包含对常用首选项的快速访问，例如屏幕分辨率、壁纸设置、窗口装饰等。</p><p>同 FVWM 中的几乎所有东西一样，你可以编辑菜单中你要想的内容，但 FVWM-Crystal 的特色在于其应用菜单栏。应用菜单位于屏幕的左上角，每个图标都包含了相关的应用启动器的菜单。例如，GIMP 图标表示图像编辑器，KDevelop 图标表示集成开发环境（IDE），GNU 图标表示文本编辑器，等等，具体取决于你在系统上安装的程序。</p><p><img src="https://opensource.com/sites/default/files/advent-fvwm-crystal.jpg" alt="FVWM-crystal running on Slackware 14.2" title="FVWM-crystal running on Slackware 14.2"></p><p>FVWM-Crystal 还提供了虚拟桌面、任务栏、时钟和应用栏。</p><p>关于背景，你可以使用与 FVWM-Crystal 捆绑在一起的壁纸，也可以使用 <code>feh</code> 命令设置自己的壁纸（你可能需要从仓库中安装它）。此命令有一些设置背景的选项，包括 <code>--bg-scale</code> 使用你选择的图片缩放填充屏幕，<code>--bg-fill</code> 直接填充而不缩放图片，等等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ feh --bg-scale ~/Pictures/wallpapers/mybackground.jpg</span></span></code></pre></div><p>大多数配置文件都包含在 <code>$HOME/.fvwm-crystal</code> 中，某些系统范围的默认文件位于 <code>/usr/share/fvwm-crystal</code>。</p><h3 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to 自己尝试一下">​</a></h3><p>FVWM 是大多作为一个桌面构建平台，它也是窗口管理器。它不会为你做到面面俱到，它期望你来配置尽可能的一切。</p><p>如果你正在寻找轻巧、快速且简单的窗口管理器，那么 FVWM 可以胜任。但是，如果你正在寻找可以深入、探索和魔改的窗口管理器，那么 FVWM 是必须的。</p><hr>',17)),s("p",null,[t[11]||(t[11]=e("via: ")),l(o,{href:"https://opensource.com/article/19/12/fvwm-linux-desktop"},{default:i(()=>t[10]||(t[10]=[e("https://opensource.com/article/19/12/fvwm-linux-desktop")])),_:1})]),s("p",null,[t[16]||(t[16]=e("作者：")),l(o,{href:"https://opensource.com/users/seth"},{default:i(()=>t[12]||(t[12]=[e("Seth Kenlon")])),_:1}),t[17]||(t[17]=e(" 选题：")),l(o,{href:"https://github.com/lujun9972"},{default:i(()=>t[13]||(t[13]=[e("lujun9972")])),_:1}),t[18]||(t[18]=e(" 译者：")),l(o,{href:"https://github.com/geekpi"},{default:i(()=>t[14]||(t[14]=[e("geekpi")])),_:1}),t[19]||(t[19]=e(" 校对：")),l(o,{href:"https://github.com/wxy"},{default:i(()=>t[15]||(t[15]=[e("wxy")])),_:1})]),s("p",null,[t[22]||(t[22]=e("本文由 ")),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>t[20]||(t[20]=[e("LCTT")])),_:1}),t[23]||(t[23]=e(" 原创编译，")),l(o,{href:"https://linux.cn/"},{default:i(()=>t[21]||(t[21]=[e("Linux中国")])),_:1}),t[24]||(t[24]=e(" 荣誉推出"))])])}const k=n(d,[["render",m]]);export{w as __pageData,k as default};
